import random,heapq
from eywa.offline import CampaignCompiler
random.seed(2025)

def ref_plan(camp,entry):
    defs={d['name']:d for d in camp['types']}
    mods={m['name']:m for m in camp['modules']}
    deps={n:set() for n in mods}
    for caller,callee in camp['calls']: deps[caller].add(callee)
    pipes_by={}
    for p in camp['pipes']:
        deps[p['target']].add(p['filter']);pipes_by.setdefault(p['target'],[]).append(p)
    # closure
    seen=set();stack=[entry]
    while stack:
        n=stack.pop()
        if n in seen:continue
        seen.add(n);stack.extend(deps[n])
    indeg={n:len(deps[n]&seen) for n in seen};out={n:[] for n in seen}
    for n in seen:
        for d in deps[n]&seen:out[d].append(n)
    h=[n for n,d in indeg.items() if d==0];heapq.heapify(h);order=[]
    while h:
        n=heapq.heappop(h);order.append(n)
        for x in out[n]:
            indeg[x]-=1
            if indeg[x]==0:heapq.heappush(h,x)
    # types
    out_types=[];emitted=set();walked=set()
    def walk_name(name):
        if name in walked:return
        walked.add(name);d=defs[name];k=d['kind']
        if k=='alias':walk_name(d['target'])
        elif k=='struct':
            for _,tn in d['fields']:walk_name(tn)
        elif k=='array':walk_name(d['element'])
        if k in ('enum','struct','alias') and name not in emitted:
            emitted.add(name);out_types.append(name)
    for mn in order:
        m=mods[mn]
        for _,tn in m['params']:walk_name(tn)
        walk_name(m['result'][1])
    # slots
    slots=[];counter=[0];expected=set()
    def build(name,path):
        d=defs[name];k=d['kind']
        while k=='alias':
            name=d['target'];d=defs[name];k=d['kind']
        if k=='void':return
        if k in ('bool','char'):
            n=counter[0];counter[0]+=1;slots.append([f'x{n}',list(path),1]);expected.add(n);return
        if k=='int':
            bits=d['bits'];w=1 if bits<=8 else 2 if bits<=16 else 4 if bits<=32 else 8
            n=counter[0];counter[0]+=1;slots.append([f'x{n}',list(path),w]);expected.add(n);return
        if k=='enum':
            n=counter[0];counter[0]+=1;slots.append([f'x{n}',list(path),4]);expected.add(n);return
        if k=='string':
            counter[0]+=1
            for i in range(d['maxsize']):
                n=counter[0];counter[0]+=1;slots.append([f'x{n}',list(path+[i]),1]);expected.add(n)
            return
        if k=='array':
            counter[0]+=1
            for i in range(d['size']):build(d['element'],path+[i])
            return
        if k=='struct':
            counter[0]+=1
            for fn,tn in d['fields']:build(tn,path+[fn])
            return
        raise Exception(k)
    m=mods[entry]
    for pn,tn in m['params']:build(tn,[pn])
    rn,rt=m['result'];build(rt,[rn])
    flag=None
    if pipes_by.get(entry):flag=f'x{counter[0]}';counter[0]+=1
    return order,out_types,slots,flag,counter[0]

# random campaign generator
for trial in range(1000):
    types=[{'name':'Bool','kind':'bool'},{'name':'Char','kind':'char'},{'name':'Int','kind':'int','bits':random.choice([1,7,8,9,16,24,32,33,64])},{'name':'Void','kind':'void'}]
    names=['Bool','Char','Int','Void']
    for i in range(random.randint(0,20)):
        name=f'T{i}';kind=random.choice(['string','enum','array','struct','alias','int','bool'])
        if kind=='string':d={'name':name,'kind':kind,'maxsize':random.randint(0,3)}
        elif kind=='enum':d={'name':name,'kind':kind,'values':['a']}
        elif kind=='array':d={'name':name,'kind':kind,'element':random.choice(names),'size':random.randint(0,3)}
        elif kind=='struct':d={'name':name,'kind':kind,'fields':[[f'f{j}',random.choice(names)] for j in range(random.randint(0,3))]}
        elif kind=='alias':d={'name':name,'kind':kind,'target':random.choice(names)}
        elif kind=='int':d={'name':name,'kind':kind,'bits':random.choice([1,8,9,17,64])}
        else:d={'name':name,'kind':kind}
        types.append(d);names.append(name)
    nm=random.randint(1,8);mods=[]
    for i in range(nm):
        params=[[f'p{j}',random.choice(names)] for j in range(random.randint(0,3))]
        # sometimes result void
        rt='Void' if random.random()<0.4 else random.choice(names)
        mods.append({'name':f'M{i}','params':params,'result':['r',rt],'requires':None})
    calls=[]
    for i in range(1,nm):
        if random.random()<0.6: calls.append([f'M{i}',f'M{random.randrange(i)}'])
        if random.random()<0.4: calls.append([f'M{i}',f'M{random.randrange(i)}'])
    pipes=[]
    for i in range(1,nm):
        if random.random()<0.6:
            f=random.randrange(i);target=f'M{i}';filt=f'M{f}'
            # bind filter params to compatible-ish arbitrary target param names (not used by ref)
            fm=mods[f]
            bind={pn:(mods[i]['params'][0][0] if mods[i]['params'] else 'x') for pn,_ in fm['params']}
            pipes.append({'target':target,'filter':filt,'bind':bind})
    camp={'types':types,'modules':mods,'calls':calls,'pipes':pipes,'entries':['M0'],'machine':None,'runs':[]}
    try:
        comp=CampaignCompiler(camp); got=comp.plans[0]
    except Exception as e:
        print('compiler error trial',trial,e);raise
    ro,rt,rs,rf,rv=ref_plan(camp,'M0')
    if got.module_order!=ro or got.type_names!=rt or got.layout.slots!=rs or got.layout.flag!=rf or got.layout.variables!=rv:
        print('MISMATCH trial',trial)
        print('camp',camp)
        print('got',got.module_order,got.type_names,got.layout.slots,got.layout.flag,got.layout.variables)
        print('ref',ro,rt,rs,rf,rv)
        break
else: print('all plan fuzz ok')
